using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Runtime.InteropServices;
namespace DashCanvas {
public static partial class Decoration {
 static Color Shade(Color c,float value){return Color.FromArgb(Math.Min(255,(int)(c.R*value)),Math.Min(255,(int)(c.G*value)),Math.Min(255,(int)(c.B*value)));}
 static GraphicsPath Outline(string shape,RectangleF r){var p=new GraphicsPath();if(shape=="Circle")p.AddEllipse(r);else if(shape=="Diamond")p.AddPolygon(new[]{new PointF(r.X+r.Width/2,r.Y),new PointF(r.Right,r.Y+r.Height/2),new PointF(r.X+r.Width/2,r.Bottom),new PointF(r.X,r.Y+r.Height/2)});else if(shape=="Hexagon")p.AddPolygon(new[]{new PointF(r.X+r.Width*.25f,r.Y),new PointF(r.X+r.Width*.75f,r.Y),new PointF(r.Right,r.Y+r.Height/2),new PointF(r.X+r.Width*.75f,r.Bottom),new PointF(r.X+r.Width*.25f,r.Bottom),new PointF(r.X,r.Y+r.Height/2)});else {float d=Math.Min(r.Width,r.Height)*(shape=="Rectangle"?.025f:.15f);p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();}return p;}
 static void Stroke(Graphics g,GraphicsPath p,Color c,float width){using(var pen=new Pen(c,Math.Max(.25f,width))){pen.LineJoin=LineJoin.Round;g.DrawPath(pen,p);}}
 static void GlowStroke(Graphics g,GraphicsPath p,Color color,float line,float glow){for(int i=8;i>=1;i--)Stroke(g,p,Color.FromArgb((int)(5+glow*.18f),color),line+i*line*.65f);Stroke(g,p,color,line*1.5f);Stroke(g,p,Color.FromArgb(245,245,255),line*.45f);}
 public static RectangleF ContentBounds(Bitmap image){int left=image.Width,top=image.Height,right=-1,bottom=-1;var data=image.LockBits(new Rectangle(0,0,image.Width,image.Height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{var row=new byte[image.Width*4];for(int y=0;y<image.Height;y++){Marshal.Copy(IntPtr.Add(data.Scan0,y*data.Stride),row,0,row.Length);for(int x=0;x<image.Width;x++)if(row[x*4+3]>16){left=Math.Min(left,x);right=Math.Max(right,x);top=Math.Min(top,y);bottom=y;}}}finally{image.UnlockBits(data);}return right<left?new RectangleF(0,0,image.Width,image.Height):new RectangleF(left,top,right-left+1,bottom-top+1);}
 public static Color ImageColor(Bitmap image){var weights=new double[512];var reds=new double[512];var greens=new double[512];var blues=new double[512];for(int y=0;y<image.Height;y+=Math.Max(1,image.Height/80))for(int x=0;x<image.Width;x+=Math.Max(1,image.Width/80)){var c=image.GetPixel(x,y);if(c.A<100||c.GetBrightness()<.08f||c.GetBrightness()>.94f)continue;int i=(c.R/32)*64+(c.G/32)*8+c.B/32;double w=.2+c.GetSaturation();weights[i]+=w;reds[i]+=c.R*w;greens[i]+=c.G*w;blues[i]+=c.B*w;}int best=0;for(int i=1;i<512;i++)if(weights[i]>weights[best])best=i;return weights[best]==0?Color.Cyan:Color.FromArgb((int)(reds[best]/weights[best]),(int)(greens[best]/weights[best]),(int)(blues[best]/weights[best]));}
 public static void DrawFrame(Bitmap image,Design d){DrawFrame(image,d,RectangleF.Empty);}
 public static void DrawFrame(Bitmap image,Design d,RectangleF bounds){if(bounds.IsEmpty)bounds=new RectangleF(0,0,image.Width,image.Height);float m=Math.Min(bounds.Width,bounds.Height);if(m<5)return;float line=Math.Max(.6f,m*d.FrameWidth/100f);bool neon=d.FrameStyle.Contains("Neon");float inset=d.FrameStyle=="Plain"?line/2:neon?line*.75f:d.FrameStyle=="Carved Wood"?line*2:line*1.7f;inset=Math.Min(inset+m*d.FrameInset/100f,m*.43f);var rect=new RectangleF(bounds.X+inset,bounds.Y+inset,bounds.Width-2*inset,bounds.Height-2*inset);
  using(var g=Graphics.FromImage(image))using(var path=Outline(d.Shape,rect)){g.SmoothingMode=SmoothingMode.AntiAlias;g.CompositingQuality=CompositingQuality.HighQuality;
   if(d.FrameStyle=="Plain"){Stroke(g,path,d.FrameColor,line);return;}
   if(neon){GlowStroke(g,path,d.FrameColor,line,d.Glow);if(d.FrameStyle=="Double Neon"){var inner=rect;inner.Inflate(-line*3,-line*3);if(inner.Width>1&&inner.Height>1)using(var p=Outline(d.Shape,inner))GlowStroke(g,p,Shade(d.FrameColor,.6f),line*.6f,d.Glow*.6f);}return;}
   if(d.FrameStyle=="Antique Gold"||d.FrameStyle=="Ornate Corners"||d.FrameStyle=="Scrollwork"){Stroke(g,path,Shade(d.FrameColor,.25f),line*3.4f);Stroke(g,path,d.FrameColor,line*2.5f);Stroke(g,path,Shade(d.FrameColor,1.4f),line*.65f);var inner=rect;inner.Inflate(-line*2.5f,-line*2.5f);if(inner.Width>2&&inner.Height>2)using(var p=Outline(d.Shape,inner))Stroke(g,p,Shade(d.FrameColor,.8f),line*.5f);if(d.FrameStyle!="Antique Gold"&&Rectangular(d.Shape))Corners(g,rect,d.FrameColor,line,d.FrameStyle=="Scrollwork");}
   else if(d.FrameStyle=="Carved Wood"){Stroke(g,path,Shade(d.FrameColor,.28f),line*4);Stroke(g,path,d.FrameColor,line*3.1f);Stroke(g,path,Shade(d.FrameColor,1.35f),line*.6f);using(var region=new Region(path)){var inner=rect;inner.Inflate(-line*2,-line*2);if(inner.Width>1&&inner.Height>1)using(var inside=Outline(d.Shape,inner))region.Exclude(inside);var save=g.Save();g.SetClip(region,CombineMode.Replace);using(var grain=new Pen(Color.FromArgb(85,35,15,7),Math.Max(.4f,line*.16f)))for(int i=0;i<32;i++){float y=rect.Top+i*rect.Height/31;g.DrawBezier(grain,rect.Left,y,rect.Left+rect.Width*.3f,y-line,rect.Left+rect.Width*.7f,y+line,rect.Right,y);}g.Restore(save);}if(Rectangular(d.Shape))Corners(g,rect,Shade(d.FrameColor,1.7f),line,false);}
  }
 }
 static bool Rectangular(string shape){return shape!="Circle"&&shape!="Diamond"&&shape!="Hexagon";}
 static void Corners(Graphics g,RectangleF r,Color color,float line,bool scroll){float len=Math.Min(r.Width,r.Height)*.19f;foreach(int x in new[]{0,1})foreach(int y in new[]{0,1}){float cx=x==0?r.Left:r.Right,cy=y==0?r.Top:r.Bottom,sx=x==0?1:-1,sy=y==0?1:-1;var save=g.Save();g.TranslateTransform(cx,cy);g.ScaleTransform(sx,sy);using(var p=new Pen(color,Math.Max(.7f,line*.75f))){g.DrawLines(p,new[]{new PointF(0,len),new PointF(0,0),new PointF(len,0)});g.DrawBezier(p,0,len*.8f,len*.3f,len*.8f,len*.1f,len*.1f,len*.8f,0);if(scroll){g.DrawArc(p,len*.14f,len*.14f,len*.52f,len*.52f,15,290);g.DrawBezier(p,len*.7f,0,len*.95f,len*.5f,len*.1f,len*.95f,0,len*.7f);}}using(var b=new SolidBrush(Shade(color,1.3f)))g.FillPolygon(b,new[]{new PointF(line,0),new PointF(line*2,line),new PointF(line,line*2),new PointF(0,line)});g.Restore(save);}}
 public static void DrawText(Bitmap image,string text,Design d,bool glyph){if(String.IsNullOrEmpty(text))return;float m=Math.Min(image.Width,image.Height);float margin=glyph?Math.Max(.5f,m*.04f):Math.Max(2,m*(d.Border&&d.FrameStyle.Contains("Neon")?.24f:d.Border&&d.FrameStyle!="Plain"&&d.FrameStyle!="None"?.15f:.1f));var region=new RectangleF(margin,margin,Math.Max(1,image.Width-2*margin),Math.Max(1,image.Height-2*margin));
  FontFamily family;try{family=new FontFamily(d.FontFamily);}catch{family=new FontFamily("Segoe UI");}
  using(family)using(var path=new GraphicsPath())using(var format=(StringFormat)StringFormat.GenericTypographic.Clone()){
   FontStyle style=(d.Bold?FontStyle.Bold:FontStyle.Regular)|(d.Italic?FontStyle.Italic:FontStyle.Regular);if(!family.IsStyleAvailable(style))style=FontStyle.Regular;
   if(glyph)path.AddString(text,family,(int)style,100,new PointF(0,0),format);else LabelPath(path,text,family,style,format,d);if(path.PointCount==0)return;var bounds=path.GetBounds();float scale=Math.Min(region.Width/Math.Max(1,bounds.Width),region.Height/Math.Max(1,bounds.Height));if(!glyph)scale=Math.Min(scale,image.Height*d.TextSize/100f/Math.Max(1,bounds.Height));float w=bounds.Width*scale,h=bounds.Height*scale;float y=region.Y+(region.Height-h)/2;if(!glyph&&d.TextPosition=="Top")y=region.Top;if(!glyph&&d.TextPosition=="Bottom")y=region.Bottom-h;
   float blockX=!glyph&&d.TextAlign=="Left"?region.Left:!glyph&&d.TextAlign=="Right"?region.Right-w:region.X+(region.Width-w)/2;using(var transform=new Matrix(scale,0,0,scale,blockX-bounds.X*scale,y-bounds.Y*scale))path.Transform(transform);
   float line=Math.Max(.5f,h*.015f*d.TextStroke);using(var g=Graphics.FromImage(image)){g.SmoothingMode=SmoothingMode.AntiAlias;
    if(d.TextEffect=="Neon")GlowStroke(g,path,d.TextColor,line,65);
    else if(d.TextEffect=="Shadow"){using(var shadow=(GraphicsPath)path.Clone())using(var shift=new Matrix()){shift.Translate(line*2,line*2);shadow.Transform(shift);using(var b=new SolidBrush(Color.FromArgb(200,0,0,0)))g.FillPath(b,shadow);}}
    else if(d.TextEffect=="Outline")Stroke(g,path,d.TextOutlineColor,line*3);else if(d.TextEffect=="Double Outline"){Stroke(g,path,d.TextOutlineColor,line*5);Stroke(g,path,Color.White,line*2.5f);}else if(d.TextEffect=="Emboss"||d.TextEffect=="Engraved")Relief(g,path,line,d.TextEffect=="Engraved");
    if(d.TextEffect=="Gold"){var bnd=path.GetBounds();using(var brush=new LinearGradientBrush(new RectangleF(bnd.X,bnd.Y,Math.Max(1,bnd.Width),Math.Max(1,bnd.Height)),Shade(d.TextColor,1.5f),Shade(d.TextColor,.5f),90f))g.FillPath(brush,path);Stroke(g,path,Shade(d.TextColor,.3f),line*.6f);}
    else if(d.TextEffect=="Gradient"){var r=path.GetBounds();using(var b=new LinearGradientBrush(new RectangleF(r.X,r.Y,Math.Max(1,r.Width),Math.Max(1,r.Height)),d.TextColor,d.TextColor2,90f))g.FillPath(b,path);}else using(var b=new SolidBrush(d.TextColor))g.FillPath(b,path);
   }
  }
 }
}
